import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.*;

public class HibTest {

    @Entity
    @Table(name = "jhi_date_time_wrapper")
    public static class DateTimeWrapper {
        @Id
        @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "sequenceGenerator")
        @SequenceGenerator(name = "sequenceGenerator")
        private Long id;

        @Column(name = "instant")
        private Instant instant;

        @Column(name = "local_date_time")
        private LocalDateTime localDateTime;

        @Column(name = "offset_date_time")
        private OffsetDateTime offsetDateTime;

        @Column(name = "zoned_date_time")
        private ZonedDateTime zonedDateTime;

        @Column(name = "local_time")
        private LocalTime localTime;

        @Column(name = "offset_time")
        private OffsetTime offsetTime;

        @Column(name = "local_date")
        private LocalDate localDate;
    }

    @Entity
    @Table(name = "bank_account")
    public static class BankAccount {
        @Id
        @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "sequenceGenerator")
        @SequenceGenerator(name = "sequenceGenerator")
        @Column(name = "id")
        private Long id;

        @Column(name = "name", nullable = false)
        private String name;

        @Column(name = "balance", precision = 21, scale = 2, nullable = false)
        private BigDecimal balance;
    }

    public static void main(String[] args) {
        // Ask Hibernate to generate DDL for H2 and print it
        java.util.Map<String, Object> settings = new java.util.HashMap<>();
        settings.put("jakarta.persistence.jdbc.url", "jdbc:h2:mem:ddlprobe;DB_CLOSE_DELAY=-1");
        settings.put("jakarta.persistence.jdbc.user", "sa");
        settings.put("jakarta.persistence.jdbc.password", "");
        settings.put("jakarta.persistence.schema-generation.database.action", "drop-and-create");
        settings.put("hibernate.hbm2ddl.auto", "create-drop");
        settings.put("hibernate.show_sql", "false");
        settings.put("hibernate.format_sql", "false");
        settings.put("hibernate.highlight_sql", "false");

        org.hibernate.cfg.AvailableSettings av = null; // (reference only)

        java.util.List<Class<?>> classes = java.util.Arrays.asList(DateTimeWrapper.class, BankAccount.class);
        try (org.hibernate.jpa.boot.internal.EntityManagerFactoryBuilderImpl ignored = null) {}
        try {
            jakarta.persistence.EntityManagerFactory emf = new org.hibernate.jpa.HibernatePersistenceProvider()
                .createContainerEntityManagerFactory(
                    new jakarta.persistence.spi.PersistenceUnitInfo() {
                        @Override
                        public String getPersistenceUnitName() {
                            return "probe";
                        }

                        @Override
                        public String getPersistenceProviderClassName() {
                            return "org.hibernate.jpa.HibernatePersistenceProvider";
                        }

                        @Override
                        public ClassLoader getNewTempClassLoader() {
                            return null;
                        }

                        @Override
                        public ClassLoader getClassLoader() {
                            return HibTest.class.getClassLoader();
                        }

                        @Override
                        public void addTransformer(jakarta.persistence.spi.ClassTransformer transformer) {}

                        @Override
                        public java.util.Properties getProperties() {
                            java.util.Properties p = new java.util.Properties();
                            p.putAll(settings);
                            return p;
                        }

                        @Override
                        public String getPersistenceXMLSchemaVersion() {
                            return "3.0";
                        }

                        @Override
                        public java.util.List<jakarta.persistence.spi.PersistenceUnitTransactionType> getTransactionType() {
                            return null;
                        }

