import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.EnumSet;
import org.hibernate.boot.Metadata;
import org.hibernate.boot.MetadataSources;
import org.hibernate.boot.registry.StandardServiceRegistry;
import org.hibernate.boot.registry.StandardServiceRegistryBuilder;
import org.hibernate.tool.schema.TargetType;
import org.hibernate.tool.schema.SourceType;
import org.hibernate.tool.schema.SchemaExport;
import org.hibernate.tool.schema.SchemaValidator;
import org.hibernate.tool.schema.SourceDescriptor;
import org.hibernate.tool.schema.internal.ScriptSourceInputFromReader;

public class HibTest {

    @Entity
    @Table(name = "jhi_date_time_wrapper")
    public static class DateTimeWrapper {
        @Id
        @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "sequenceGenerator")
        @SequenceGenerator(name = "sequenceGenerator")
        private Long id;

        @Column(name = "instant")
        private Instant instant;

        @Column(name = "local_date_time")
        private LocalDateTime localDateTime;

        @Column(name = "offset_date_time")
        private OffsetDateTime offsetDateTime;

        @Column(name = "zoned_date_time")
        private ZonedDateTime zonedDateTime;

        @Column(name = "local_time")
        private LocalTime localTime;

        @Column(name = "offset_time")
        private OffsetTime offsetTime;

        @Column(name = "local_date")
        private LocalDate localDate;
    }

    @Entity
    @Table(name = "bank_account")
    public static class BankAccount {
        @Id
        @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "sequenceGenerator")
        @SequenceGenerator(name = "sequenceGenerator")
        @Column(name = "id")
        private Long id;

        @Column(name = "name", nullable = false)
        private String name;

        @Column(name = "balance", precision = 21, scale = 2, nullable = false)
        private BigDecimal balance;
    }

    public static void main(String[] args) throws Exception {
        StandardServiceRegistryBuilder rb = new StandardServiceRegistryBuilder();
        rb.applySetting("hibernate.connection.url", "jdbc:h2:mem:ddlprobe;DB_CLOSE_DELAY=-1");
        rb.applySetting("hibernate.connection.username", "sa");
        rb.applySetting("hibernate.connection.password", "");
        rb.applySetting("hibernate.dialect", "org.hibernate.dialect.H2Dialect");
        rb.applySetting("hibernate.hbm2ddl.auto", "none");
        StandardServiceRegistry registry = rb.build();

        MetadataSources sources = new MetadataSources(registry);
        sources.addAnnotatedClass(DateTimeWrapper.class);
        sources.addAnnotatedClass(BankAccount.class);
        Metadata metadata = sources.buildMetadata();

        System.out.println("=========== EXPECTED DDL (Hibernate 6.2.13 on H2) ===========");
        SchemaExport export = new SchemaExport();
        export.setFormat(false);
        export.setHaltOnError(false);
        export.createOnly(EnumSet.of(TargetType.STDOUT), metadata);

        System.out.println("=========== DIALECT: " + metadata.getDatabase().getDialect().getClass().getName() + " ===========");

