            st.execute("CREATE SEQUENCE IF NOT EXISTS sequence_generator START WITH 1050 INCREMENT BY 50");
            st.execute(
                "CREATE TABLE jhi_date_time_wrapper (id BIGINT NOT NULL, instant TIMESTAMP, local_date_time TIMESTAMP," +
                " offset_date_time TIMESTAMP, zoned_date_time TIMESTAMP, local_time TIME, offset_time TIME, local_date DATE," +
                " CONSTRAINT jhi_date_time_wrapperPK PRIMARY KEY (id))"
            );
            st.execute("CREATE TABLE bank_account (id BIGINT NOT NULL, name VARCHAR(255), balance NUMERIC(21,2), PRIMARY KEY (id))");
        }
