            SchemaValidator validator = new SchemaValidator();
            validator.validate(metadata);
            System.out.println("VALIDATION PASSED");
        } catch (Exception e) {
            System.out.println("VALIDATION FAILED:");
            e.printStackTrace(System.out);
        }
        conn.close();
        registry.close();
    }
}

