import org.hibernate.boot.registry.StandardServiceRegistry;
import org.hibernate.boot.registry.StandardServiceRegistryBuilder;

public class LiqTest {

    @Entity
    @jakarta.persistence.Table(name = "jhi_date_time_wrapper")
    public static class DateTimeWrapper {
        @jakarta.persistence.Id
        @jakarta.persistence.GeneratedValue(strategy = jakarta.persistence.GenerationType.SEQUENCE, generator = "sequenceGenerator")
        @jakarta.persistence.SequenceGenerator(name = "sequenceGenerator")
        private Long id;

        @jakarta.persistence.Column(name = "instant")
        private Instant instant;

        @jakarta.persistence.Column(name = "local_date_time")
        private LocalDateTime localDateTime;

        @jakarta.persistence.Column(name = "offset_date_time")
        private OffsetDateTime offsetDateTime;

        @jakarta.persistence.Column(name = "zoned_date_time")
        private ZonedDateTime zonedDateTime;

        @jakarta.persistence.Column(name = "local_time")
        private LocalTime localTime;

        @jakarta.persistence.Column(name = "offset_time")
        private OffsetTime offsetTime;

        @jakarta.persistence.Column(name = "local_date")
        private LocalDate localDate;
    }

    public static void main(String[] args) throws Exception {
        String url = "jdbc:h2:mem:liqtest;DB_CLOSE_DELAY=-1";
        Connection conn = DriverManager.getConnection(url, "sa", "");
        Database database = DatabaseFactory.getInstance().findCorrectDatabaseImplementation(new JdbcConnection(conn));
        Liquibase liquibase = new Liquibase(
            "config/liquibase/master.xml",
            new DirectoryResourceAccessor(new java.io.File("/work/src/main/resources")),
            database
        );
        liquibase.update(new liquibase.Contexts("test"), new liquibase.Labels());
        System.out.println("=== LIQUIBASE UPDATE DONE ===");
        try (Statement st = conn.createStatement()) {
            ResultSet rs = st.executeQuery("SCRIPT");
            while (rs.next()) {
                String line = rs.getString(1);
                String u = line.toUpperCase();
                if (u.contains("DATE_TIME_WRAPPER") || u.contains("SEQUENCE")) {
                    System.out.println(line);
                }
            }
        }

        StandardServiceRegistryBuilder rb = new StandardServiceRegistryBuilder();
        rb.applySetting("hibernate.connection.url", url);
        rb.applySetting("hibernate.connection.username", "sa");
        rb.applySetting("hibernate.connection.password", "");
        rb.applySetting("hibernate.hbm2ddl.auto", "validate");
        rb.applySetting("hibernate.jdbc.time_zone", "UTC");
        rb.applySetting("hibernate.implicit_naming_strategy", "org.springframework.boot.orm.jpa.hibernate.SpringImplicitNamingStrategy");
        rb.applySetting("hibernate.physical_naming_strategy", "org.hibernate.boot.model.naming.CamelCaseToUnderscoresNamingStrategy");
        StandardServiceRegistry registry = rb.build();
        Metadata metadata = new MetadataSources(registry).addAnnotatedClass(DateTimeWrapper.class).buildMetadata();
        try (SessionFactory sf = metadata.buildSessionFactory()) {
            System.out.println("=== VALIDATION PASSED ===");
            org.hibernate.Session s = sf.openSession();
            s.getTransaction().begin();
            DateTimeWrapper w = new DateTimeWrapper();
            set(w, "instant", Instant.parse("2014-11-12T05:50:00.0Z"));
            set(w, "localDateTime", LocalDateTime.parse("2014-11-12T07:50:00.0"));
            set(w, "offsetDateTime", OffsetDateTime.parse("2011-12-14T08:30:00.0Z"));
            set(w, "zonedDateTime", ZonedDateTime.parse("2011-12-14T08:30:00.0Z"));
            set(w, "localTime", LocalTime.parse("14:30:00"));
            set(w, "offsetTime", OffsetTime.parse("14:30:00+02:00"));
            set(w, "localDate", LocalDate.parse("2016-09-10"));
            s.persist(w);
            s.getTransaction().commit();
            s.close();
        } catch (Exception e) {
            System.out.println("=== HIBERNATE FAILED ===");
            e.printStackTrace(System.out);
        }
        try (Statement st = conn.createStatement()) {
            ResultSet rs = st.executeQuery(
                "SELECT id, instant, local_date_time, offset_date_time, zoned_date_time, local_time, offset_time, local_date" +
                " FROM jhi_date_time_wrapper ORDER BY id DESC LIMIT 1"
            );
            if (rs.next()) {
                for (int i = 1; i <= 8; i++) {
                    System.out.println("  " + rs.getMetaData().getColumnName(i) + " = [" + rs.getString(i) + "]");
                }
            }
        }
        conn.close();
    }

    private static void set(Object target, String field, Object value) throws Exception {
        java.lang.reflect.Field f = target.getClass().getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }
}

