Operation fetchLabels(Operation result) {
    return entityManager
        .createQuery("select operation from Operation operation left join fetch operation.labels where operation is :operation", Operation.class)
        .setParameter("operation", result)
        .getSingleResult();
}

List<Operation> fetchLabels(List<Operation> operations) {
    HashMap<Object, Integer> order = new HashMap<>();
    IntStream.range(0, operations.size()).forEach(index -> order.put(operations.get(index).getId(), index));
    List<Operation> result = entityManager
        .createQuery("select distinct operation from Operation operation left join fetch operation.labels where operation in :operations", Operation.class)
        .setParameter("operations", operations)
        .getResultList();
    Collections.sort(result, (o1, o2) -> Integer.compare(order.get(o1.getId()), order.get(o2.getId())));
    return result;
}

