import javax.servlet.http.HttpServletRequest;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.authentication.AnonymousAuthenticationToken;
import org.springframework.security.authentication.TestingAuthenticationToken;
import org.springframework.security.access.SecurityConfig;
import org.springframework.security.access.vote.AffirmativeBased;
import org.springframework.security.access.vote.RoleVoter;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.authority.AuthorityUtils;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.web.access.intercept.DefaultFilterInvocationSecurityMetadataSource;
import org.springframework.security.web.access.intercept.FilterInvocationSecurityMetadataSource;
import org.springframework.security.web.access.intercept.FilterSecurityInterceptor;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

import java.util.Arrays;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

public class SS5Test {
    public static void main(String[] args) throws Exception {
        // Reproduce the JHipster 5.7 authorizeRequests() map WITHOUT anyRequest()
        Map<AntPathRequestMatcher, Collection<SecurityConfig>> requestMap = new LinkedHashMap<>();
        requestMap.put(new AntPathRequestMatcher("/api/**"), SecurityConfig.createList("authenticated"));
        FilterInvocationSecurityMetadataSource metadataSource =
            new DefaultFilterInvocationSecurityMetadataSource(requestMap);

        FilterSecurityInterceptor interceptor = new FilterSecurityInterceptor();
        interceptor.setSecurityMetadataSource(metadataSource);
        AffirmativeBased adm = new AffirmativeBased(Arrays.asList(new RoleVoter()));
        interceptor.setAccessDecisionManager(adm);
        interceptor.setAuthenticationManager((AuthenticationManager) authentication -> authentication);
        interceptor.afterPropertiesSet();

        Authentication anon = new AnonymousAuthenticationToken(
            "key", "anon", AuthorityUtils.createAuthorityList("ROLE_ANONYMOUS"));
        SecurityContextHolder.getContext().setAuthentication(anon);

        // unmatched request: GET /index.html (not under /api/**)
        MockHttpServletRequest req = new MockHttpServletRequest("GET", "/index.html");
        try {
            Object result = interceptor.beforeInvocation(req);
            System.out.println("UNMATCHED request: PERMITTED (result=" + result + ")");
        } catch (Exception e) {
            System.out.println("UNMATCHED request: REJECTED -> " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        SecurityContextHolder.clearContext();
    }
}
EOF
